import{_ as e,o as i,c as r,a4 as o}from"./chunks/framework.BAxM5-cj.js";const u=JSON.parse('{"title":"Sprint 5 — Authentication & RBAC","description":"","frontmatter":{},"headers":[],"relativePath":"plan/sprints/Sprint_05_Authentication_RBAC.md","filePath":"plan/sprints/Sprint_05_Authentication_RBAC.md"}'),a={name:"plan/sprints/Sprint_05_Authentication_RBAC.md"};function n(d,t,s,l,c,h){return i(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="sprint-5-—-authentication-rbac" tabindex="-1">Sprint 5 — Authentication &amp; RBAC <a class="header-anchor" href="#sprint-5-—-authentication-rbac" aria-label="Permalink to &quot;Sprint 5 — Authentication &amp; RBAC&quot;">​</a></h1><p><strong>Timeline:</strong> Weeks 9–10 (Jul 15–28, 2026) <strong>Jira:</strong> DA Sprint 5 <strong>Phase:</strong> Phase 3 — Backend Core <strong>Goal:</strong> Implement the complete authentication system (register, login, OAuth, token refresh, logout) and role-based access control enforcement in business-service.</p><p>&gt; <strong>AI Parallel:</strong> AI Iteration 1 runs concurrently this sprint.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Epic</th><th>Title</th><th>Owner</th></tr></thead><tbody><tr><td>E12</td><td>Authentication</td><td>Trung</td></tr><tr><td>E13</td><td>User &amp; Profile Management</td><td>Trung, Ân</td></tr><tr><td>E14</td><td>Role-Based Access Control (RBAC)</td><td>Trung, Phước</td></tr></tbody></table><p><strong>Deliverables by end of Sprint 5:</strong></p><ul><li>Register / Login / Logout / Refresh Token APIs working</li><li>Google OAuth login working (callback + user creation)</li><li>Forgot Password / Reset Password flow working</li><li>Avatar upload to S3 working</li><li>Admin user management APIs (list, ban/suspend)</li><li>RBAC annotation enforced on all endpoints</li><li>Workspace isolation filter active (workspaceId required on all queries)</li><li>Permission matrix document</li></ul><hr><h2 id="epic-e12-—-authentication" tabindex="-1">EPIC E12 — Authentication <a class="header-anchor" href="#epic-e12-—-authentication" aria-label="Permalink to &quot;EPIC E12 — Authentication&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E12-01</td><td>Implement Register API (validate email uniqueness, hash password with bcrypt cost=12)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E12-02</td><td>Implement Login API (verify password, issue JWT access token 15 min + refresh token 30 days)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E12-03</td><td>Implement Refresh Token API (verify refresh token, issue new access token)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E12-04</td><td>Implement Logout API (add JWT jti to Redis blacklist, clear cookie)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E12-05</td><td>Implement Forgot Password &amp; Reset Password flow (email link with time-limited token)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E12-06</td><td>Implement Google OAuth login (callback handler, create user if not exists)</td><td>Trung (Leader)</td><td>🟡 High</td></tr></tbody></table><p><strong>JWT specification:</strong></p><ul><li>Access token: 15 min TTL, signed with RS256, payload: <code>{sub: userId, role, workspaceId, jti}</code></li><li>Refresh token: 30 days TTL, stored in HttpOnly cookie + MongoDB <code>users.refreshTokens[]</code></li><li>Blacklist: Redis <code>jwt:blacklist:{jti}</code> with TTL = remaining access token lifetime</li></ul><p><strong>Reset password token:</strong> random UUID, stored in Redis <code>pwd:reset:{token}</code> with TTL = 1 hour.</p><p><strong>Notes:</strong></p><ul><li>DA-E12-05: use AWS SES or a transactional email service (SendGrid free tier) for password reset emails.</li><li>DA-E12-06: Google OAuth scope = <code>openid email profile</code>. On callback, check if email exists → login; else create new user with role=AGENCY_OWNER (default for self-registration).</li><li>Never store plain-text passwords. bcrypt cost=12 is the minimum — do not lower for &quot;performance&quot;.</li></ul><hr><h2 id="epic-e13-—-user-profile-management" tabindex="-1">EPIC E13 — User &amp; Profile Management <a class="header-anchor" href="#epic-e13-—-user-profile-management" aria-label="Permalink to &quot;EPIC E13 — User &amp; Profile Management&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E13-01</td><td>Implement GET/PUT /api/v1/users/me (get and update own profile)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E13-02</td><td>Implement avatar upload (receive file → upload to S3 → save URL to MongoDB)</td><td>Trung (Leader)</td><td>🟡 High</td></tr><tr><td>DA-E13-03</td><td>Implement Admin: GET /api/v1/admin/users (list all users with filters)</td><td>Ân (AI)</td><td>🟡 High</td></tr><tr><td>DA-E13-04</td><td>Implement Admin: Ban/Suspend user (set isActive=false, send notification)</td><td>Ân (AI)</td><td>🟡 High</td></tr></tbody></table><p><strong>Avatar upload (DA-E13-02):</strong></p><ul><li>Accept: JPEG, PNG, WebP. Max size: 5MB.</li><li>S3 key: <code>avatars/{userId}/{timestamp}.{ext}</code></li><li>Return presigned URL with 7-day TTL.</li><li>Validate content-type from file header, not just extension.</li></ul><hr><h2 id="epic-e14-—-role-based-access-control-rbac" tabindex="-1">EPIC E14 — Role-Based Access Control (RBAC) <a class="header-anchor" href="#epic-e14-—-role-based-access-control-rbac" aria-label="Permalink to &quot;EPIC E14 — Role-Based Access Control (RBAC)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E14-01</td><td>Write RBAC annotation/middleware for business-service (@RequireRole)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E14-02</td><td>Implement workspace isolation filter (every MongoDB query must include workspaceId filter)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E14-03</td><td>Implement client isolation for BRAND_CLIENT (can only view data belonging to their clientId)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E14-04</td><td>Write permission matrix document (6 roles x all endpoints = allowed/denied)</td><td>Phước (Publisher)</td><td>🟢 Medium</td></tr></tbody></table><p><strong>RBAC implementation:</strong></p><ul><li>Extract <code>X-User-Role</code> from gateway-injected header (set by JWT filter in Sprint 4)</li><li><code>@RequireRole({AGENCY_OWNER, ADMIN})</code> annotation on controller methods</li><li>Return 403 Forbidden if role not in allowed list</li></ul><p><strong>Workspace isolation:</strong></p><ul><li>Spring <code>@Bean</code> request-scoped <code>WorkspaceContext</code> holding <code>workspaceId</code> from JWT</li><li>Custom MongoDB repository base class injects <code>{workspaceId: ctx.workspaceId}</code> into every query</li><li>BRAND_CLIENT: additionally inject <code>{clientId: ctx.clientId}</code> filter</li></ul><hr><h2 id="sprint-5-checklist" tabindex="-1">Sprint 5 Checklist <a class="header-anchor" href="#sprint-5-checklist" aria-label="Permalink to &quot;Sprint 5 Checklist&quot;">​</a></h2><ul><li>[ ] POST /api/v1/auth/register creates user, returns JWT</li><li>[ ] POST /api/v1/auth/login returns access + refresh tokens</li><li>[ ] POST /api/v1/auth/refresh issues new access token</li><li>[ ] POST /api/v1/auth/logout blacklists JWT in Redis</li><li>[ ] Forgot password email sent, reset link works within 1h</li><li>[ ] Google OAuth redirect → callback → user created/logged in</li><li>[ ] GET/PUT /api/v1/users/me working with auth</li><li>[ ] Avatar upload: file → S3 → URL saved to user profile</li><li>[ ] Admin can list users with pagination and role filter</li><li>[ ] Admin can ban a user (isActive=false enforced on login)</li><li>[ ] @RequireRole enforced: wrong role returns 403</li><li>[ ] workspaceId filter active: cannot access other workspace&#39;s data</li><li>[ ] BRAND_CLIENT clientId isolation: cannot see other clients&#39; data</li><li>[ ] Permission matrix document committed</li></ul>',31)])])}const m=e(a,[["render",n]]);export{u as __pageData,m as default};
